CREATE TYPE public.app_role AS ENUM ('admin','doctor','receptionist','assistant');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT false, doctor_id uuid REFERENCES public.doctors(id));
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.staff_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, role public.app_role NOT NULL, doctor_id uuid REFERENCES public.doctors(id), active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.staff_invitations TO authenticated; GRANT ALL ON public.staff_invitations TO service_role;
ALTER TABLE public.staff_invitations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND p.active); $$;
CREATE FUNCTION public.is_clinic_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=auth.uid() AND p.active); $$;
CREATE FUNCTION public.own_doctor() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT doctor_id FROM public.profiles WHERE id=auth.uid() AND active AND public.has_role(auth.uid(),'doctor'); $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY invitations_read ON public.staff_invitations FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.sync_staff_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.staff_invitations; BEGIN SELECT * INTO v FROM public.staff_invitations WHERE lower(email)=lower(NEW.email); INSERT INTO public.profiles(id,name,email,active,doctor_id) VALUES(NEW.id,coalesce(v.name,NEW.raw_user_meta_data->>'name',''),coalesce(NEW.email,''),coalesce(v.active,false) AND NEW.email_confirmed_at IS NOT NULL,v.doctor_id) ON CONFLICT(id) DO UPDATE SET email=excluded.email,active=excluded.active; IF v.id IS NOT NULL AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,v.role) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role; END IF; RETURN NEW; END; $$;
CREATE TRIGGER clinic_staff_signup AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.sync_staff_identity();
COMMENT ON TABLE public.system_users IS 'DEPRECATED: replaced by profiles, user_roles and Cloud Auth. Legacy passwords must never be used.';
REVOKE ALL ON public.system_users FROM anon,authenticated;
DO $$ DECLARE t text; p record; BEGIN FOREACH t IN ARRAY ARRAY['tickets','appointments','doctors','doctor_types','offices','medical_records','prescriptions','queue_rules','ticket_counters'] LOOP FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,t); END LOOP; EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['doctors','doctor_types','offices','queue_rules'] LOOP EXECUTE format('GRANT SELECT ON public.%I TO anon',t); EXECUTE format('CREATE POLICY catalog_read ON public.%I FOR SELECT TO anon,authenticated USING(true)',t); EXECUTE format('CREATE POLICY catalog_admin ON public.%I FOR ALL TO authenticated USING(public.has_role(auth.uid(),''admin'')) WITH CHECK(public.has_role(auth.uid(),''admin''))',t); END LOOP; END $$;
CREATE POLICY tickets_read ON public.tickets FOR SELECT TO authenticated USING(public.is_clinic_staff());
CREATE POLICY tickets_reception ON public.tickets FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'receptionist'));
CREATE POLICY tickets_update ON public.tickets FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'receptionist') OR doctor_id=public.own_doctor()) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'receptionist') OR doctor_id=public.own_doctor());
CREATE POLICY tickets_delete ON public.tickets FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY appointments_read ON public.appointments FOR SELECT TO authenticated USING(public.is_clinic_staff());
CREATE POLICY appointments_manage ON public.appointments FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'receptionist')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'receptionist'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['medical_records','prescriptions'] LOOP EXECUTE format('CREATE POLICY clinical_read ON public.%I FOR SELECT TO authenticated USING(public.has_role(auth.uid(),''admin'') OR public.has_role(auth.uid(),''doctor''))',t); EXECUTE format('CREATE POLICY clinical_write ON public.%I FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),''admin'') OR EXISTS(SELECT 1 FROM public.tickets t WHERE t.id=ticket_id AND t.doctor_id=public.own_doctor() AND t.status=''em_atendimento_medico''))',t); END LOOP; END $$;
CREATE POLICY counters_admin ON public.ticket_counters FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.queue_display (id uuid PRIMARY KEY, code text NOT NULL, priority text NOT NULL, specialty_id text NOT NULL, status text NOT NULL, patient_name text, office_name text, doctor_id uuid, created_at timestamptz NOT NULL, called_at timestamptz, hora_chegada timestamptz NOT NULL, hora_chamada_recepcao timestamptz, hora_fim_recepcao timestamptz, hora_chamada_medico timestamptz, hora_fim_atendimento timestamptz);
GRANT SELECT ON public.queue_display TO anon,authenticated; GRANT ALL ON public.queue_display TO service_role;
ALTER TABLE public.queue_display ENABLE ROW LEVEL SECURITY;
CREATE POLICY display_read ON public.queue_display FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.sync_queue_display() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN DELETE FROM public.queue_display WHERE id=OLD.id; RETURN OLD; END IF; INSERT INTO public.queue_display VALUES(NEW.id,NEW.code,NEW.priority,NEW.specialty_id,NEW.status,CASE WHEN NEW.called_at IS NOT NULL THEN NEW.patient_name ELSE NULL END,NEW.office_name,NEW.doctor_id,NEW.created_at,NEW.called_at,NEW.hora_chegada,NEW.hora_chamada_recepcao,NEW.hora_fim_recepcao,NEW.hora_chamada_medico,NEW.hora_fim_atendimento) ON CONFLICT(id) DO UPDATE SET status=excluded.status,patient_name=excluded.patient_name,office_name=excluded.office_name,doctor_id=excluded.doctor_id,called_at=excluded.called_at,hora_chamada_recepcao=excluded.hora_chamada_recepcao,hora_fim_recepcao=excluded.hora_fim_recepcao,hora_chamada_medico=excluded.hora_chamada_medico,hora_fim_atendimento=excluded.hora_fim_atendimento; RETURN NEW; END; $$;
CREATE TRIGGER ticket_display AFTER INSERT OR UPDATE OR DELETE ON public.tickets FOR EACH ROW EXECUTE FUNCTION public.sync_queue_display();
INSERT INTO public.queue_display SELECT id,code,priority,specialty_id,status,CASE WHEN called_at IS NOT NULL THEN patient_name END,office_name,doctor_id,created_at,called_at,hora_chegada,hora_chamada_recepcao,hora_fim_recepcao,hora_chamada_medico,hora_fim_atendimento FROM public.tickets;
ALTER PUBLICATION supabase_realtime ADD TABLE public.queue_display,public.profiles,public.user_roles;
REVOKE EXECUTE ON FUNCTION public.next_ticket_code(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.next_ticket_code(text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.call_next_reception() FROM PUBLIC,anon;
REVOKE EXECUTE ON FUNCTION public.call_next_doctor(uuid,uuid,text) FROM PUBLIC,anon;
DO $$ DECLARE n text; def text; BEGIN FOREACH n IN ARRAY ARRAY['call_next_reception','call_next_doctor','next_ticket_code'] LOOP SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=n; IF n='call_next_reception' THEN def:=replace(def,E'begin\n',E'begin\n  IF NOT (public.has_role(auth.uid(),''admin'') OR public.has_role(auth.uid(),''receptionist'')) THEN RAISE EXCEPTION ''Acesso negado''; END IF;\n'); ELSIF n='call_next_doctor' THEN def:=replace(def,E'begin\n',E'begin\n  IF NOT (public.has_role(auth.uid(),''admin'') OR (public.has_role(auth.uid(),''doctor'') AND p_doctor_id=public.own_doctor())) THEN RAISE EXCEPTION ''Acesso negado''; END IF;\n  SELECT name INTO p_office_name FROM public.offices WHERE id=p_office_id AND active; IF p_office_name IS NULL THEN RAISE EXCEPTION ''Consultório inválido''; END IF;\n'); END IF; EXECUTE def; END LOOP; END $$;
CREATE FUNCTION public.kiosk_ticket(p_priority text,p_specialty text) RETURNS SETOF public.queue_display LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF p_priority NOT IN ('normal','priority') OR p_specialty NOT IN ('1','2','3','4','5','6') THEN RAISE EXCEPTION 'Senha inválida'; END IF; INSERT INTO public.tickets(code,priority,specialty_id) VALUES(public.next_ticket_code(p_priority),p_priority,p_specialty) RETURNING id INTO v_id; RETURN QUERY SELECT * FROM public.queue_display WHERE id=v_id; END; $$;
REVOKE EXECUTE ON FUNCTION public.kiosk_ticket(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.kiosk_ticket(text,text) TO anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.sync_staff_identity(),public.sync_queue_display() FROM PUBLIC,anon,authenticated;